function taka(n) {
  return "৳" + Number(n).toLocaleString("en-IN");
}

function genId() {
  return Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
}

/* ---------- Firebase Firestore (REST API — no SDK bundle needed) ---------- */
const FIREBASE_PROJECT_ID = "amish-ebbae";
const FIRESTORE_BASE = `https://firestore.googleapis.com/v1/projects/${FIREBASE_PROJECT_ID}/databases/(default)/documents`;

async function fsGetDoc(path) {
  const res = await fetch(`${FIRESTORE_BASE}/${path}`);
  if (!res.ok) throw new Error("not found");
  const data = await res.json();
  const raw = data?.fields?.data?.stringValue;
  return raw ? JSON.parse(raw) : null;
}

async function fsSetDoc(path, value) {
  const res = await fetch(`${FIRESTORE_BASE}/${path}`, {
    method: "PATCH",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ fields: { data: { stringValue: JSON.stringify(value) } } }),
  });
  if (!res.ok) throw new Error("firestore write failed: " + res.status);
  return res.json();
}

async function fsListCollection(collectionPath) {
  const res = await fetch(`${FIRESTORE_BASE}/${collectionPath}?pageSize=300`);
  if (!res.ok) throw new Error("firestore list failed: " + res.status);
  const data = await res.json();
  if (!data.documents) return [];
  return data.documents
    .map((d) => {
      const raw = d.fields?.data?.stringValue;
      return raw ? JSON.parse(raw) : null;
    })
    .filter(Boolean);
}

/* ---------- storage helpers (backed by Firestore) ---------- */
const PRODUCTS_DOC = "products/catalog";
const ORDERS_COLLECTION = "orders";

async function loadProducts() {
  try {
    const existing = await fsGetDoc(PRODUCTS_DOC);
    if (existing) return existing;
  } catch (e) {
    /* doc not found yet, fall through to seed */
  }
  try {
    await fsSetDoc(PRODUCTS_DOC, DEFAULT_PRODUCTS);
  } catch (e) {
    /* firestore write failed — still let the app run with in-memory defaults */
  }
  return DEFAULT_PRODUCTS;
}

async function saveProducts(products) {
  await fsSetDoc(PRODUCTS_DOC, products);
}

async function loadOrders() {
  try {
    const orders = await fsListCollection(ORDERS_COLLECTION);
    return orders.sort((a, b) => b.ts - a.ts);
  } catch (e) {
    return [];
  }
}

async function saveOrder(order) {
  await fsSetDoc(`${ORDERS_COLLECTION}/${order.id}`, order);
}

async function updateOrderStatus(order) {
  await fsSetDoc(`${ORDERS_COLLECTION}/${order.id}`, order);
}


