/* ---------- Cart drawer ---------- */

function CartView({ products, cart, setCart, onBack, onCheckout }) {
  const items = Object.entries(cart)
    .map(([id, qty]) => ({ product: products.find((p) => p.id === id), qty }))
    .filter((x) => x.product);

  const subtotal = items.reduce((s, x) => s + x.product.price * x.qty, 0);
  const total = items.length ? subtotal + DELIVERY_FEE : 0;

  const setQty = (id, qty) =>
    setCart((c) => {
      const n = { ...c };
      if (qty <= 0) delete n[id];
      else n[id] = qty;
      return n;
    });

  return (
    <div style={{ background: T.bg, minHeight: "100vh" }}>
      <div className="flex items-center gap-3 px-5 py-5" style={{ background: T.deep }}>
        <button onClick={onBack} aria-label="ফিরে যান">
          <ArrowLeft color="#fff" size={20} />
        </button>
        <h2 className="font-bold" style={{ color: "#fff" }}>
          আপনার কার্ট
        </h2>
      </div>

      <div className="px-4 py-5">
        {items.length === 0 ? (
          <div className="text-center py-16">
            <PackageX size={36} style={{ color: T.mute, margin: "0 auto" }} />
            <p className="text-sm mt-3" style={{ color: T.mute }}>
              কার্ট খালি — প্রোডাক্ট যোগ করুন
            </p>
          </div>
        ) : (
          <div className="space-y-3">
            {items.map(({ product, qty }) => (
              <div
                key={product.id}
                className="flex items-center justify-between p-3 rounded-lg"
                style={{ background: T.surface, border: `1px solid ${T.line}` }}
              >
                <div className="flex-1 pr-2">
                  <p className="text-sm font-semibold" style={{ color: T.ink }}>
                    {product.name}
                  </p>
                  <p className="text-xs" style={{ color: T.mute }}>
                    {taka(product.price)} / {product.unit}
                  </p>
                </div>
                <div className="flex items-center gap-2">
                  <button
                    onClick={() => setQty(product.id, qty - 1)}
                    className="w-7 h-7 rounded-full flex items-center justify-center"
                    style={{ background: T.bg, border: `1px solid ${T.line}` }}
                  >
                    <Minus size={12} />
                  </button>
                  <span className="w-4 text-center text-sm font-semibold">{qty}</span>
                  <button
                    onClick={() => setQty(product.id, qty + 1)}
                    className="w-7 h-7 rounded-full flex items-center justify-center"
                    style={{ background: T.deep, color: "#fff" }}
                  >
                    <Plus size={12} />
                  </button>
                  <button
                    onClick={() => setQty(product.id, 0)}
                    className="w-7 h-7 rounded-full flex items-center justify-center ml-1"
                    style={{ color: T.coral }}
                    aria-label="মুছে ফেলুন"
                  >
                    <Trash2 size={14} />
                  </button>
                </div>
              </div>
            ))}

            <div className="rounded-lg p-4 mt-4" style={{ background: T.surface, border: `1px solid ${T.line}` }}>
              <div className="flex justify-between text-sm mb-1" style={{ color: T.ink }}>
                <span>সাবটোটাল</span>
                <span>{taka(subtotal)}</span>
              </div>
              <div className="flex justify-between text-sm mb-2" style={{ color: T.mute }}>
                <span>ডেলিভারি চার্জ</span>
                <span>{taka(DELIVERY_FEE)}</span>
              </div>
              <div
                className="flex justify-between font-bold pt-2"
                style={{ color: T.deep, borderTop: `1px dashed ${T.line}` }}
              >
                <span>মোট</span>
                <span>{taka(total)}</span>
              </div>
            </div>

            <button
              onClick={onCheckout}
              className="w-full py-3.5 rounded-full font-semibold text-sm mt-2"
              style={{ background: T.coral, color: "#fff" }}
            >
              অর্ডার করতে এগিয়ে যান
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

/* ---------- Checkout ---------- */

function Checkout({ products, cart, setCart, onBack, onDone }) {
  const [form, setForm] = useState({ name: "", phone: "", address: "", notes: "" });
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState("");

  const items = Object.entries(cart)
    .map(([id, qty]) => ({ product: products.find((p) => p.id === id), qty }))
    .filter((x) => x.product);
  const subtotal = items.reduce((s, x) => s + x.product.price * x.qty, 0);
  const total = subtotal + DELIVERY_FEE;

  const valid = form.name.trim() && form.phone.trim().length >= 10 && form.address.trim();

  const submit = async () => {
    if (!valid || submitting) return;
    setSubmitting(true);
    setError("");
    const order = {
      id: genId(),
      ts: Date.now(),
      name: form.name.trim(),
      phone: form.phone.trim(),
      address: form.address.trim(),
      notes: form.notes.trim(),
      items: items.map((x) => ({
        id: x.product.id,
        name: x.product.name,
        qty: x.qty,
        price: x.product.price,
        unit: x.product.unit,
      })),
      subtotal,
      deliveryFee: DELIVERY_FEE,
      total,
      status: "new",
    };
    try {
      await saveOrder(order);
      setCart({});
      onDone(order);
    } catch (e) {
      setError("অর্ডার সেভ করতে সমস্যা হয়েছে, আবার চেষ্টা করুন।");
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div style={{ background: T.bg, minHeight: "100vh" }}>
      <div className="flex items-center gap-3 px-5 py-5" style={{ background: T.deep }}>
        <button onClick={onBack} aria-label="ফিরে যান">
          <ArrowLeft color="#fff" size={20} />
        </button>
        <h2 className="font-bold" style={{ color: "#fff" }}>
          ডেলিভারি তথ্য
        </h2>
      </div>

      <div className="px-4 py-5 space-y-4">
        <Field icon={<User size={15} />} label="আপনার নাম">
          <input
            value={form.name}
            onChange={(e) => setForm({ ...form, name: e.target.value })}
            placeholder="নাম লিখুন"
            className="w-full bg-transparent outline-none text-sm"
            style={{ color: T.ink }}
          />
        </Field>
        <Field icon={<Phone size={15} />} label="ফোন নম্বর">
          <input
            value={form.phone}
            onChange={(e) => setForm({ ...form, phone: e.target.value })}
            placeholder="01XXXXXXXXX"
            inputMode="tel"
            className="w-full bg-transparent outline-none text-sm"
            style={{ color: T.ink }}
          />
        </Field>
        <Field icon={<MapPin size={15} />} label="ডেলিভারি ঠিকানা (চট্টগ্রাম সিটি)">
          <textarea
            value={form.address}
            onChange={(e) => setForm({ ...form, address: e.target.value })}
            placeholder="বাসা/রোড/এলাকার নাম লিখুন"
            rows={2}
            className="w-full bg-transparent outline-none text-sm resize-none"
            style={{ color: T.ink }}
          />
        </Field>
        <Field icon={<Pencil size={15} />} label="নোট (ঐচ্ছিক)">
          <input
            value={form.notes}
            onChange={(e) => setForm({ ...form, notes: e.target.value })}
            placeholder="বিশেষ কোনো নির্দেশনা"
            className="w-full bg-transparent outline-none text-sm"
            style={{ color: T.ink }}
          />
        </Field>

        <div className="rounded-lg p-4" style={{ background: T.surface, border: `1px solid ${T.line}` }}>
          <p className="text-xs font-semibold mb-2" style={{ color: T.mute }}>
            অর্ডার সামারি
          </p>
          {items.map((x) => (
            <div key={x.product.id} className="flex justify-between text-xs py-0.5" style={{ color: T.ink }}>
              <span>
                {x.product.name} × {x.qty}
              </span>
              <span>{taka(x.product.price * x.qty)}</span>
            </div>
          ))}
          <div
            className="flex justify-between font-bold pt-2 mt-2 text-sm"
            style={{ color: T.deep, borderTop: `1px dashed ${T.line}` }}
          >
            <span>মোট (ডেলিভারিসহ)</span>
            <span>{taka(total)}</span>
          </div>
        </div>

        {error && (
          <p className="text-xs" style={{ color: T.coral }}>
            {error}
          </p>
        )}

        <button
          onClick={submit}
          disabled={!valid || submitting}
          className="w-full py-3.5 rounded-full font-semibold text-sm"
          style={{
            background: valid ? T.coral : "#D9D9D6",
            color: "#fff",
          }}
        >
          {submitting ? "অর্ডার হচ্ছে..." : "অর্ডার কনফার্ম করুন"}
        </button>
        <p className="text-[11px] text-center" style={{ color: T.mute }}>
          অর্ডার জমা হলে আমরা কল বা WhatsApp-এ যোগাযোগ করে নিশ্চিত করবো
        </p>
      </div>
    </div>
  );
}

function Field({ icon, label, children }) {
  return (
    <div className="rounded-lg p-3.5" style={{ background: T.surface, border: `1px solid ${T.line}` }}>
      <div className="flex items-center gap-1.5 text-[11px] font-semibold mb-1.5" style={{ color: T.mute }}>
        {icon}
        {label}
      </div>
      {children}
    </div>
  );
}

/* ---------- Confirmation ---------- */

